        actionType: "passive",
        description: "Anvaca pode empunhar uma lança longa numa mão se estiver segurando um escudo na outra. Armas de lança que Anvaca empunha tornam-se temporariamente golpeador maior +2 e causam 1d8 adicional de dano de espírito num acerto.",
