    abilities: [
      {
        id: "clockwork-sentry-clockwork-creature-wind-up",
        name: "Dar Corda",
        originalName: "Wind-Up",
        actionType: "passive",
        description: "24 horas, Prestidigitação CD 26 (Desativar Dispositivo), espera.\nPara um autômato de corda agir, outra criatura precisa dar-lhe corda com uma chave única. Isso leva 1 minuto. Uma vez dado corda, permanece operacional pelo tempo listado, em geral 24 horas, depois do qual deixa de perceber o entorno e não age até receber corda de novo. Algumas habilidades de autômatos de corda exigem gastar parte do tempo operacional restante. Não podem gastar mais do que têm e desligam no instante em que chegam a 0. Se não estiver claro quando o autômato recebeu corda pela última vez, a maioria dos cuidadores dá corda a todos numa hora fixa, em geral às 8h.\nUm autômato de corda que liste espera em Dar Corda pode entrar em modo de espera como atividade de 3 ações. O tempo operacional não diminui em espera, mas ele percebe o entorno (com −2 de penalidade em Percepção). Não pode agir, com uma exceção: ao perceber uma criatura, pode sair da espera como reação (rolando iniciativa se for o caso).\nUma criatura pode tentar Desativar Dispositivo para destecer a corda (com a CD listada em Dar Corda). Cada sucesso faz o autômato perder 1 hora de tempo operacional. Isso pode ser feito mesmo em modo de espera.",
      },
      {
        id: "clockwork-sentry-constant-spells",
        name: "Magias constantes",
        originalName: "Constant Spells",
        actionType: "passive",
        description: "Uma magia constante afeta a criatura sem ela precisar conjurá-la, e a duração é ilimitada. Se a magia constante for contrariada, a criatura pode reativá-la gastando as ações de conjuração normais da magia.",
      },
      {
        id: "clockwork-sentry-sudden-seize",
        name: "Apreensão Súbita",
        originalName: "Sudden Seize",
        actionType: "reaction",
        trigger: "Uma criatura no alcance da sentinela de corda usa uma ação de manipular ou de movimento, faz um ataque à distância, ou sai de um espaço durante uma ação de movimento que está usando",
        description: "A sentinela de corda tenta um teste de Atletismo para Agarrar a criatura que disparou.",
      },
      {
        id: "clockwork-sentry-arrest",
        name: "Prender",
        originalName: "Arrest",
        actionType: "free",
        trigger: "A sentinela de corda tem uma criatura Imobilizada",
        description: "A sentinela de corda Interage para colocar algemas na criatura imobilizada.",
      },
      {
        id: "clockwork-sentry-tackle",
        name: "Derrubada",
        originalName: "Tackle",
        actionType: "two",
        description: "A sentinela de corda Anda até o dobro do Deslocamento em linha reta. Se terminar esse movimento no alcance de uma criatura, faz um Golpe de punho contra ela. Num acerto ou acerto crítico, o alvo sofre 1d6 adicional de dano de concussão e fica Caído.",
      },
      {
        id: "clockwork-sentry-grab",
        name: "Agarrar",
        originalName: "Grab",
        actionType: "one",
        requirements: "A última ação da criatura foi um Golpe bem-sucedido que lista Agarrar na entrada de dano, ou a criatura já tem um alvo agarrado ou imobilizado.",
        description: "Se usada depois de um Golpe, a criatura tenta Agarrar o alvo usando a parte do corpo com que atacou. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos. Em vez disso, a criatura pode usar Agarrar e escolher uma criatura que já esteja agarrando ou imobilizando com um apêndice que tenha Agarrar para estender automaticamente essa condição até o fim do próximo turno da criatura.",
      },
      {
        id: "clockwork-sentry-knockdown",
        name: "Derrubar",
        originalName: "Knockdown",
        actionType: "one",
        requirements: "A última ação da criatura foi um Golpe bem-sucedido que lista Derrubar na entrada de dano.",
        description: "A criatura tenta Derrubar o alvo. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos.",
      },
      {
        id: "clockwork-sentry-push",
        name: "Empurrar",
        originalName: "Push",
        actionType: "one",
        requirements: "A última ação da criatura foi um Golpe bem-sucedido que lista Empurrar na entrada de dano.",
        description: "A criatura tenta Empurrar o alvo. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos. Se Empurrar listar uma distância, use essa distância no sucesso.",
      },
    ],
    summary: "Sentinelas de corda são construtos de quatro braços criados para servir de guardiões, programados ou para impedir o acesso a um local específico ou para impedir que alvos escapem de um sítio seguro.",
