        description: "O maestro velstrac fita uma criatura que possa ver a até 9 m. A criatura deve tentar imediatamente uma salvaguarda de Vontade contra a aura de Acompanhamento Horripilante do maestro velstrac. Além disso, se a criatura já estava amedrontada, numa falha na salvaguarda sofre 1d6 de dano persistente mental. Depois de tentar esta salvaguarda, a criatura fica imune temporariamente por 1 hora.",
