        name: "Grite para Mim",
        originalName: "Scream for Me",
        actionType: "one",
        frequency: "1 vez por rodada",
        description: "Com um floreio horripilante e um sorriso faminto, o maestro velstrac aponta a batuta para uma criatura a até 30 m, compelindo-a a gritar. A criatura deve tentar uma salvaguarda de Vontade CD 28. Em falha, grita, sofrendo 4d6 de dano mental (8d6 de dano mental numa falha crítica) e causando 2d6 de dano sônico a todas as criaturas numa emanação de 6 m (salvaguarda básica de Fortitude CD 28).\nEm vez de escolher uma criatura como alvo, o maestro pode escolher como alvo todas as criaturas no alcance que foram compelidas a gritar por esta habilidade na rodada anterior.",
