        description: "O fulthrethu sustenta uma magia de Criatura Ilusória. Quando uma magia de Criatura Ilusória é sustentada desta forma, a ilusão não é destruída automaticamente se for atingida por um ataque ou falhar numa salvaguarda. Em vez disso, o fulthrethu sofre 3d6 de dano mental e deve tentar um teste simples CD 5. Em falha, a magia de Criatura Ilusória termina. O fulthrethu pode sustentar uma magia de Criatura Ilusória por até 8 horas.",
