    abilities: [
      {
        id: "kalakaigh-fear-scent",
        name: "Faro de Medo",
        originalName: "Fear Scent",
        actionType: "passive",
        description: "Um kalakaigh pode sentir criaturas amedrontadas ou sob um efeito de medo.",
      },
      {
        id: "kalakaigh-1-status-to-all-saves-vs-magic",
        name: "+1 em todas as salvaguardas contra magia",
        originalName: "+1 to All Saves vs. Magic",
        actionType: "passive",
        description: "+1 em todas as salvaguardas contra magia",
      },
      {
        id: "kalakaigh-mercy-vulnerability",
        name: "Vulnerabilidade à Misericórdia",
        originalName: "Mercy Vulnerability",
        actionType: "passive",
        description: "Kalakaighs deleitam-se com a visão de feridas frescas e, quando uma é curada, recuam de dor. Quando uma criatura cura dano que o kalakaigh causou no último turno, o demônio sofre 4d6 de dano mental. O kalakaigh só pode sofrer este dano 1 vez por rodada.",
      },
      {
        id: "kalakaigh-bloody-attack",
        name: "Ataque Sangrento",
        originalName: "Bloody Attack",
        actionType: "passive",
        description: "Um kalakaigh causa 1d6 extra de dano de precisão e 1d6 extra de dano persistente de sangramento a criaturas desprevenidas.",
      },
      {
        id: "kalakaigh-change-shape",
        name: "Mudar Forma",
        originalName: "Change Shape",
        actionType: "one",
        description: "O kalakaigh pode assumir a aparência de qualquer humanoide Médio, mas ao fazê-lo sempre parece estar vestindo roupas escuras, luvas pretas e algum tipo de cobertura que oculta o rosto ou a cabeça. Essas “roupas” são na verdade parte do corpo novo do demônio. A forma nova não muda o Deslocamento nem os modificadores de ataque e dano dos Golpes, mas impede que faça Golpes de chifre.\nA criatura muda de forma por tempo indefinido. Pode usar esta ação de novo para voltar à forma natural ou assumir outra forma. Salvo indicação em contrário, não pode usar Mudar Forma para parecer um indivíduo específico. Usar Mudar Forma conta como criar um disfarce para Personificar (Enganação). A transformação vence automaticamente as CDs de Percepção para decidir se a criatura é da ancestralidade ou do tipo em que se transformou, e ela ganha +4 de status na CD de Enganação para impedir que vejam através do disfarce. A habilidade lista as formas que pode assumir. A criatura não ganha habilidades especiais da nova forma, só o corpo: em cada forma, substitui Deslocamentos e Golpes normais, e pode mudar sentidos ou tamanho. Qualquer mudança está na ficha.",
      },
      {
        id: "kalakaigh-shocking-reveal",
        name: "Revelação Chocante",
        originalName: "Shocking Reveal",
        actionType: "reaction",
        trigger: "O kalakaigh causa dano a uma criatura com um Golpe corpo a corpo enquanto está na forma humanoide",
        description: "O kalakaigh reverte à forma verdadeira, e todas as criaturas numa emanação de 9 m que testemunhem a transformação devem fazer uma salvaguarda de Vontade CD 21 ou ficam Amedrontadas 1 (Amedrontadas 2 numa falha crítica).",
      },
      {
        id: "kalakaigh-signature-slaughter",
        name: "Massacre Característico",
        originalName: "Signature Slaughter",
        actionType: "two",
        description: "O kalakaigh ataca com um floreio reconhecível ou de um jeito específico que liga todos os assassinatos. O kalakaigh faz um Golpe corpo a corpo com o kukri. Isso conta como dois ataques ao calcular a penalidade de ataques múltiplos do demônio. Se este Golpe acertar, o kalakaigh causa 2d6 adicional de dano persistente de sangramento, e o alvo fica Amedrontado 2.",
      },
    ],
    summary: "Um kalakaigh é acima de tudo um assassino — uma encarnação infernal do pecado do assassinato.",
