        id: "strigoi-servant-void-healing",
        name: "Cura de Vazio",
        originalName: "Void Healing",
        actionType: "passive",
        description: "A criatura tira saúde da energia de vazio, não da vitalidade. Sofre dano de vitalidade e não é curada por efeitos de cura de vitalidade. Não sofre dano de vazio, e é curada por efeitos de vazio que curam mortos-vivos.",
