        description: "9 m. A urtiga-vampiro exala um aroma cativante que nenhuma criatura percebe exatamente igual, a não ser pelo caráter sedutor. Uma criatura viva que entre na aura ou comece o turno na área deve tentar uma salvaguarda de Vontade CD 15.\n**Sucesso crítico** A criatura não é afetada e fica imune temporariamente ao aroma sedutor por 24 horas.\n**Sucesso** A criatura fica Embotada 1 até o início do próximo turno.\n**Falha** A criatura fica Fascinada, e deve gastar cada uma das ações para se aproximar da urtiga-vampiro o mais depressa possível, evitando perigos óbvios. Se uma criatura fascinada estiver adjacente a uma urtiga-vampiro, permanece parada e não age. Se atacada pela urtiga-vampiro, a criatura é libertada do cativeiro no fim do turno da urtiga-vampiro.\n**Falha crítica** Como falha, mas se atacada pela urtiga-vampiro, a criatura pode tentar uma nova salvaguarda no início do próximo turno, em vez de ser libertada no fim do turno da urtiga-vampiro.",
