        requirements: "Uma criatura Agarrada, Paralisada, Contida, Inconsciente ou disposta está no alcance do vampiro",
        description: "O vampiro crava as presas nessa criatura para beber-lhe o sangue. Isso exige um teste de Atletismo contra a CD de Fortitude da vítima se ela estiver Agarrada, e é automático para as outras condições.\nA vítima fica Drenada 1 e o vampiro recupera 5 PV, ganhando qualquer PV excedente como PV temporários. Beber Sangue de uma criatura já drenada não restaura PV ao vampiro, mas aumenta o valor de Drenado em 1, matando a vítima ao chegar a Drenado 5. Um vampiro também pode consumir sangue esvaziado num recipiente para sustento, mas não ganha PV com isso.\nO Drenado da vítima diminui em 1 por semana. Uma transfusão de sangue, que exige um teste de Medicina CD 20 e sangue suficiente ou um doador, reduz o Drenado em 1 após 10 minutos.",
