        description: "Se for reduzido a 0 PV, Vikandian dispersa-se numa imensa quantidade de ratos individuais que fogem em todas as direções na tentativa de voltar ao caixão na área **N6**. Se nem que seja um rato entrar neste caixão, ele se reforma no corpo e fica Inconsciente. Se o corpo descansar no caixão por 1 hora, Vikandian ganha 1 PV, depois do que a cura acelerada volta a funcionar normalmente. Se o caixão não contiver terra pestilenta de túmulo, em vez disso precisa descansar no caixão por 1 dia antes de ganhar 1 PV e recuperar a cura acelerada.",
