        description: "O nosferatu pode conjurar Dominar à vontade como magia inata divina. Conjurar exige fitar os olhos do alvo, dando à magia o traço visual (Vontade CD 26). Uma criatura que passe fica imune temporariamente ao Dominar daquele nosferatu por 24 horas. Destruir o nosferatu por completo encerra a dominação, mas apenas reduzi-lo a 0 PV não basta para quebrar a magia.",
