        id: "vikandian-vampire-nosferatu-drink-blood",
        name: "Beber Sangue",
        originalName: "Drink Blood",
        actionType: "one",
        requirements: "A última ação do nosferatu foi um Golpe de presas bem-sucedido",
        description: "O nosferatu crava as presas na criatura alvo para beber-lhe o sangue. Isso exige um teste de Atletismo contra a CD de Fortitude da criatura. Em sucesso, a criatura fica Drenada 1, e Vikandian recupera 10 PV, ganhando qualquer PV excedente como PV temporários e ganhando panache. Beber Sangue de uma criatura já drenada não restaura PV ao nosferatu, mas aumenta o valor de Drenado em 1. Um nosferatu também pode consumir sangue esvaziado num recipiente para sustento, mas não ganha PV com isso.\nO valor de Drenado da criatura alvo diminui em 1 por semana. Uma transfusão de sangue, que exige um teste de Medicina CD 20 bem-sucedido e sangue suficiente ou um doador, reduz o valor de Drenado em 1 após 10 minutos.",
