        description: "Zovi luta usando um dispositivo complexo que fabricou com peças de mecanismos saqueadas e magitec azlanti antiga. Semelhante a um gancho de arpéu preso a um cabo de recolhimento automático, este dispositivo chama-se inovação gancho de combate. Permite a Zovi usar as habilidades Propulsão Magitécnica e Rajada Rodopiante. Diferente de outras armas com cabo, cada vez que Zovi usa a inovação gancho de combate, ela a recupera automaticamente como ação livre, permitindo vários ataques em sequência. De resto, funciona como uma inovação de arma de inventor sem modificações.",
